// SPA route -> console API it reads. All under /api, all session-cookie auth.
// /                GET  /api/fleet                         -> { counts, servers[] }
// /triage          GET  /api/triage?window=15m             -> { verdicts[], rows[] }
//                  GET  /api/triage/callers?server=&window=
// /servers/:n      GET  /api/servers/:n                     -> config + live status
//                  GET  /api/servers/:n/tools              -> [{name, tokens, enabled, calls24h, errRate, p95}]
//                  GET  /api/servers/:n/health?window=24h  -> rollup buckets
//                  POST /api/servers/:n/restart | /sleep | /wake
//                  POST /api/servers/:n/secrets            (write-only, never returned)
// /servers/new     POST /api/servers/probe -> {probeId}; GET /api/servers/probe/:id; POST /api/servers
// /groups          GET  /api/groups ; POST|PATCH|DELETE /api/groups/:slug
//                  GET  /api/groups/:slug/preview          -> literal tools/list payload
// /tools           GET  /api/tools?server=&group=&q=&cursor=
//                  PATCH /api/tools/:server/:tool          -> { enabled?, description? }
//                  POST  /api/tools/:server/:tool/invoke
// /logs            GET  /api/logs?server=&level=&q=&before=&limit=  (history; also the CLI surface)
// /activity        GET  /api/activity?...&before= ; GET /api/activity/:id
// /cost            GET  /api/cost                          -> { servers[], groups[], smart{withPD,withoutPD} }
// /market          GET  /api/catalog?q=&cursor= ; GET /api/catalog/:id
// /keys            GET|POST /api/keys ; DELETE /api/keys/:id     (better-auth apiKey plugin)
// /users           GET /api/users ; POST /api/users/invite ; PATCH /api/users/:id
// /settings/:sec   GET /api/settings ; PATCH /api/settings   (partial, zod-validated)
// (all)            GET  /api/events                         (SSE, cookie only)

export type Topic = 'status' | 'log' | 'call' | 'sync' | 'changed';
export type ServerState = 'connected'|'connecting'|'disconnected'|'sleeping'|'auth_required'|'error';

export type Frame =
  | { t:'hello';   seq:number; at:string; serverTime:string; topics:Topic[]; ringMin:number }
  | { t:'status';  seq:number; at:string; server:string; state:ServerState;
                   toolsExposed:number; toolsGross:number; lastError:string|null; since:string }
  | { t:'log';     seq:number; at:string; level:'debug'|'info'|'warn'|'error';
                   server:string|null; requestId:string|null; msg:string }
  | { t:'call';    seq:number; at:string; id:string; server:string; tool:string; durationMs:number;
                   status:'ok'|'error'|'denied'|'timeout'; principalLabel:string;
                   clientName:string|null; groupSlug:string|null }
  | { t:'sync';    seq:number; at:string; phase:'idle'|'embedding'|'done'|'error'; done:number; total:number }
  | { t:'changed'; seq:number; at:string; domain:'servers'|'groups'|'keys'|'users'|'settings'|'catalog'; id?:string }
  | { t:'dropped'; seq:number; at:string; topic:Topic; count:number }
  | { t:'gap';     seq:number; at:string; from:number };

// ---- server -------------------------------------------------------------
app.get('/api/events', requireRole('viewer'), (c) => {
  const stream = bus.subscribe({
    topics: (c.req.query('topics') ?? 'status,call,sync,changed').split(',') as Topic[],
    server: c.req.query('server') ?? null,          // filtering is SERVER-SIDE: a viewer must never
    level:  c.req.query('level')  ?? 'info',        // receive lines it is not allowed to see
    resume: Number(c.req.header('Last-Event-ID')) || 0,
    principal: c.get('user'),
  });
  return new Response(stream, { headers: {
    'content-type':'text/event-stream', 'cache-control':'no-store',
    'x-accel-buffering':'no', 'connection':'keep-alive' }});
});

// bus.subscribe() returns a ReadableStream that:
//  1. writes `retry: 1000` then a `hello` frame carrying ringMin
//  2. replays ring.slice(resume) when resume >= ringMin, else emits `gap`
//  3. writes each live frame as `id: <seq>\ndata: <json>\n\n`
//  4. writes `:\r\n` every 15s as keep-alive
//  5. SLOW CONSUMER: on controller.desiredSize <= 0 it drops `log` frames only
//     (they are replayable from GET /api/logs), counts them, and emits one
//     `dropped` frame per second. status/call/sync/changed are never dropped —
//     status and sync coalesce latest-wins per server, call and changed are rare.
//     ponytail: in-process ring, single replica. Multi-replica needs a shared
//     bus (LISTEN/NOTIFY); the frame shape does not change.

// ---- client -------------------------------------------------------------
const DOMAIN_KEY = { servers: qk.servers(), groups: qk.groups(), keys: qk.keys(),
                     users: qk.users(), settings: qk.settings(), catalog: ['catalog'] } as const;

const bumpMetrics = debounce(2000, () => {
  qc.invalidateQueries({ queryKey: ['metrics'],  refetchType: 'active' });
  qc.invalidateQueries({ queryKey: ['activity'], refetchType: 'active' });
});

export function connectEvents(params: URLSearchParams) {
  const es = new EventSource(`/api/events?${params}`);   // cookie auth, same-origin, no withCredentials
  es.onmessage = (e) => {
    const f: Frame = JSON.parse(e.data);
    switch (f.t) {
      case 'status':  patchStatus(f); break;                                   // PATCH
      case 'sync':    qc.setQueryData(qk.embeddings(), f); break;              // PATCH
      case 'call':    callTail.push(f); bumpMetrics(); break;                  // ring + debounced invalidate
      case 'log':     logTail.push(f); break;                                  // ring only, never Query
      case 'changed': qc.invalidateQueries({ queryKey: DOMAIN_KEY[f.domain], refetchType:'active' }); break;
      case 'dropped': logTail.note(f.count); break;
      case 'gap':     logTail.clear(); qc.invalidateQueries(); break;
      case 'hello':   break;                                                   // ringMin already handled by `gap`
    }
  };
  es.onerror = () => {/* EventSource reconnects natively using our `retry: 1000`
     and replays Last-Event-ID. The banner shows `reconnecting` after 3s of
     readyState===CONNECTING; no custom backoff loop is written. */};
  return () => es.close();
}

const STATUS_FIELDS = ['state','toolsExposed','toolsGross','lastError','since'] as const;
function patchStatus(f: Extract<Frame,{t:'status'}>) {
  const patch = Object.fromEntries(STATUS_FIELDS.map(k => [k, f[k]]));
  qc.setQueryData(qk.servers(), (rows?: ServerRow[]) =>
    rows?.map(r => r.name === f.server ? { ...r, ...patch } : r));
  qc.setQueryData(qk.server(f.server), (r?: ServerRow) => r && { ...r, ...patch });
  qc.setQueryData(qk.fleet(), (fl?: Fleet) => fl && { ...fl,
    servers: fl.servers.map(r => r.name === f.server ? { ...r, ...patch } : r) });
}

// logTail / callTail: bounded arrays (5000 / 500) behind useSyncExternalStore,
// notify batched on requestAnimationFrame. Not React state, not Query.
// The whole SSE layer is one module and ~120 lines.

export const callEvent = pgTable('call_event', {
  id:            bigserial({ mode: 'number' }).primaryKey(),   // descending page cursor
  startedAt:     timestamp({ withTimezone: true }).notNull().defaultNow(),
  durationMs:    integer().notNull(),
  server:        text().notNull(),
  tool:          text().notNull(),                             // BARE name; qualified = server||sep||tool
  groupSlug:     text(),
  status:        text({ enum: ['ok','error','denied','timeout'] }).notNull(),
  errorCode:     text(),
  principalKind: text({ enum: ['key','user','console'] }).notNull(),
  principalId:   text().notNull(),
  principalLabel:text().notNull(),        // key name / email, denormalised: survives revocation
  clientName:    text(), clientVersion: text(),   // clientInfo, resolved at the HTTP edge
  requestId:     text().notNull(),        // joins to log lines
  sourceIp:      text(),
  tokensIn:      integer(), tokensOut: integer(),
  args:          jsonb(), result: jsonb(),// null when policy says metadata-only
  payloadPolicy: text({ enum: ['stored','omitted','truncated'] }).notNull(),
}, t => [
  index('call_event_window').on(t.server, t.startedAt.desc()),   // triage live window
  index('call_event_principal').on(t.principalId, t.startedAt.desc()),
  index('call_event_req').on(t.requestId),
]);

export const callRollup1m = pgTable('call_rollup_1m', {
  bucket: timestamp({ withTimezone: true }).notNull(),
  server: text().notNull(),
  n:      integer().notNull().default(0),
  nErr:   integer().notNull().default(0),
  sumMs:  bigint({ mode: 'number' }).notNull().default(0),
  maxMs:  integer().notNull().default(0),
}, t => [primaryKey({ columns: [t.bucket, t.server] }),
         index('rollup_server_bucket').on(t.server, t.bucket.desc())]);

// written with the call row, same txn, no worker:
//   INSERT INTO call_rollup_1m (bucket, server, n, n_err, sum_ms, max_ms)
//   VALUES (date_trunc('minute', $at), $server, 1, $isErr, $ms, $ms)
//   ON CONFLICT (bucket, server) DO UPDATE SET
//     n = call_rollup_1m.n + 1, n_err = call_rollup_1m.n_err + EXCLUDED.n_err,
//     sum_ms = call_rollup_1m.sum_ms + EXCLUDED.sum_ms,
//     max_ms = greatest(call_rollup_1m.max_ms, EXCLUDED.max_ms);
// ponytail: rollup carries mean+max, not p95. True p95 is computed over the live
// window from raw rows. Upgrade to a t-digest column when the window must exceed 15m.

import { z } from 'zod';
type Section = 'general'|'routing'|'embeddings'|'observability'|'retention'|'network'|'marketplace'|'advanced';
type Meta = { section: Section; label: string; help?: string; keywords?: string[];
              control?: 'switch'|'number'|'text'|'secret'|'select'|'duration'; danger?: true };
export const ui = z.registry<Meta>();

export const settingsSchema = z.object({
  routing: z.object({
    nameSeparator: z.enum(['-','__','.']).default('-')
      .register(ui, { section:'routing', label:'Namespace separator',
        help:'Tools are exposed to clients as <server><sep><tool>. Changing this renames every tool.',
        keywords:['prefix','namespace','collision'], danger:true }),
    smartEnabled: z.boolean().default(true)
      .register(ui, { section:'routing', label:'Smart Routing', control:'switch',
        help:'Replaces the tool list on $smart routes with search_tools / call_tool.' }),
    progressiveDisclosure: z.boolean().default(true)
      .register(ui, { section:'routing', label:'Progressive disclosure',
        help:'Adds describe_tool and returns name+description only from search_tools.' }),
    searchThreshold: z.number().min(0).max(1).default(0.3)
      .register(ui, { section:'routing', label:'Vector match threshold', control:'number' }),
  }),
  retention: z.object({
    activityDays: z.number().int().min(1).max(365).default(14)
      .register(ui, { section:'retention', label:'Keep call records for', control:'duration' }),
    storeToolPayloads: z.boolean().default(false)
      .register(ui, { section:'retention', label:'Store tool arguments and results',
        help:'Payloads are stored VERBATIM — no redaction heuristic runs.', danger:true }),
  }),
  /* general, embeddings, observability, network, marketplace, advanced … */
});
export type Settings = z.infer<typeof settingsSchema>;

// ~40 lines, three consumers:
export const descriptors = flatten(settingsSchema);  // [{ path:'routing.searchThreshold', meta, node }]
//  -> SettingsSection renders descriptors.filter(d => d.meta.section === section)
//  -> search index:  Fuse-less; d.meta.label + d.meta.help + d.meta.keywords + d.path, substring match
//  -> cmdk palette:  "go to setting …" entries navigate to /settings/<section>#<path>
// Server: app.patch('/api/settings', v => settingsSchema.partial({deep:true}).parse(v))

